// The trigger may hand us the object directly, inside "body", or as a 1-item array
let root = $json.body ?? $json;
if (Array.isArray(root)) root = root[0];
const d = root?.data;

// 1. Only brand-new inbound messages. Ignore sent messages, delivery receipts, etc.
if (root?.event !== 'message:in:new' || !d) return [];
if (d.flow !== 'inbound') return [];   // stops the bot replying to itself in an endless loop

// 2. Ignore groups, broadcasts, channels and system notifications
const m = d.meta || {};
if (m.isGroup || m.isBroadcast || m.isChannel || m.isNotification || m.isBizNotification) return [];

// 3. Sender's number in +E.164 form, e.g. +234XXXXXXXXXX
const phone = d.fromNumber
  || d.chat?.contact?.phone
  || (d.from ? '+' + String(d.from).split('@')[0] : '');
if (!phone) return [];

return [{
  json: {
    message_id: d.id,
    phone,
    chat_id: d.chat?.id ?? d.from,
    name: m.notifyName || d.chat?.contact?.displayName || d.chat?.contact?.name || 'there',
    type: d.type,   // "text", "image", "ptt", "document", "location" ...
    text: d.type === 'text' ? String(d.body ?? '').trim() : '',
    received_at: d.date ?? new Date().toISOString(),
    device_phone: root.device?.phone ?? d.toNumber
  }
}];

const b = $json;
return [{ json: {
  phone: b.phone, message_id: b.message_id, intent: 'non_text', question: '[' + b.type + ']',
  service_key: '', reply_text: 'Thanks for your message! I can only read text messages for now. Could you type your question?',
  action: 'non_text_reply', result: 'ok', error: '', escalate: false, reason: '',
  alert_text: '', has_lead: false, lead: null
}}];

const base = $('Normalize Message').first().json;
const config = {};
for (const item of $input.all()) config[item.json.key] = item.json.value;
return [{ json: { ...base, config } }];

const base = $('Merge Config').first().json;

const raw = typeof $json.output === 'string' ? $json.output
  : $json.output?.[0]?.content?.[0]?.text
  ?? $json.message?.content
  ?? $json.choices?.[0]?.message?.content
  ?? $json.content?.[0]?.text
  ?? $json.text ?? '';

// Safety net: urgent words always go to the emergency FAQ
const urgent = /\bswell|\bswollen|bleeding (won['’]?t|wont|will not)|heavy bleeding|can['’]?t stop bleeding|can['’]?t breathe|cannot breathe|(difficulty|trouble) (breathing|swallowing)|knocked[- ]out|severe pain/i
  .test(base.text || '');
if (urgent) {
  return [{ json: { ...base, profile_name: base.name, intent: 'faq', faq_key: 'emergency',
    service_key: 'unknown', confidence: 1, needs_human: false, valid: true, reason: 'urgent_keywords' } }];
}

const INTENTS = ['pricing_question','faq','lead_inquiry','booking_request','other'];
const SERVICE_KEYS = ['consultation','xray_single','xray_panoramic','cleaning','fluoride_treatment','sealant','kids_cleaning','filling','root_canal','crown','partial_denture','full_denture','extraction_simple','extraction_surgical','dental_implant','whitening','whitening_kit','veneers','bonding','braces_metal','clear_aligners','retainer','gum_treatment','night_guard','emergency_visit','premium_package','unknown'];
const FAQ_KEYS = ['opening_hours','location','parking_access','contact_phone','after_hours','how_to_book','reschedule_cancel','late_arrival','walk_ins','first_visit','what_to_bring','consultation_duration','languages','payment_methods','installment_plans','hmo_insurance','deposit','price_estimates','receipts','pain_comfort','dental_anxiety','sterilization','xray_safety','pregnancy','children','whitening_info','braces_info','implants_info','aftercare_extraction','aftercare_whitening','emergency','complaints_feedback','privacy','contact_human','about_assistant','none'];

const fail = (reason, extra = {}) =>
  [{ json: { ...base, profile_name: base.name, ...extra, valid: false, reason } }];

let p = null;
try { p = JSON.parse(String(raw).replace(/```(?:json)?/gi, '').trim()); } catch (e) {}
if (!p || typeof p !== 'object' || Array.isArray(p)) return fail('invalid_json');

const confidence = Number(p.confidence);
if (!INTENTS.includes(p.intent) || !Number.isFinite(confidence) || confidence < 0 || confidence > 1
    || typeof p.needs_human !== 'boolean') return fail('invalid_json_shape');

const str = v => (typeof v === 'string' && v.trim() ? v.trim() : null);
const out = {
  ...base,                       // base stays authoritative
  profile_name: base.name,
  intent: p.intent,
  service_key: SERVICE_KEYS.includes(p.service_key) ? p.service_key : 'unknown',
  faq_key: FAQ_KEYS.includes(p.faq_key) ? p.faq_key : 'none',
  name: str(p.name) || base.name,
  stated_name: str(p.name),
  budget: str(p.budget),
  timeline: str(p.timeline),
  preferred_datetime: Number.isNaN(Date.parse(p.preferred_datetime)) ? null : p.preferred_datetime,
  confidence,
  needs_human: p.needs_human,
};

if (out.intent === 'other') return fail('other_intent', out);
if (out.intent === 'faq' && out.faq_key === 'none') return fail('bad_faq_key', out);
if (confidence < 0.6 || out.needs_human) return fail('low_confidence', out);
return [{ json: { ...out, valid: true } }];

// INPUT: the Pricing row found by "Lookup Price" (an empty item when nothing matched)
const ctx = $('Validate AI JSON').first().json;
const row = $input.first()?.json ?? {};
const cfg = ctx.config || {};
const wait = cfg.human_response_time || 'shortly';
const maxAge = Number(cfg.price_staleness_days) || 30;
const get = k => row[k] ?? row[`${k} (auto)`];   // tolerates headers such as "price_display (auto)"
const nm = ctx.stated_name || ctx.name;
const who = nm && nm !== 'there' ? ' ' + nm : '';

const p = { phone: ctx.phone, message_id: ctx.message_id, intent: ctx.intent, question: ctx.text,
  service_key: ctx.service_key || '', reply_text: '', action: '', result: 'ok', error: '',
  escalate: false, reason: '', alert_text: '', has_lead: false, lead: null };

// Price: accepts 25000, "25000", "25,000" or "₦25,000"
const rawPrice = String(get('price_ngn') ?? '').trim();
const price = Number(rawPrice.replace(/[^0-9.]/g, ''));
const hasPrice = rawPrice !== '' && Number.isFinite(price) && price > 0;

// Date: accepts "2026-10-06", a normal date string, or a Google/Excel serial number
const toDate = v => {
  if (v === undefined || v === null || String(v).trim() === '') return null;
  const s = String(v).trim();
  if (/^\d{5}(\.\d+)?$/.test(s)) return new Date(Math.round((Number(s) - 25569) * 86400000));
  const d = /^\d{4}-\d{2}-\d{2}/.test(s) ? new Date(s.slice(0, 10) + 'T00:00:00Z') : new Date(s);
  return isNaN(d) ? null : d;
};

let reason = '';
if (!get('service_key')) reason = ctx.service_key === 'unknown' ? 'unknown_service' : 'service_not_found';
else if (String(get('status') ?? '').trim().toLowerCase() !== 'active') reason = 'inactive_service';
else if (!hasPrice) reason = 'missing_price';
else {
  const updated = toDate(get('last_updated'));
  const age = updated ? (Date.now() - updated.getTime()) / 86400000 : NaN;
  if (!Number.isFinite(age) || age > maxAge) reason = 'stale_price';
}

if (reason) {
  p.reply_text = reason === 'unknown_service'
    ? `Thanks for asking! I couldn't find that service in our price list, so I've asked a team member to check for you. They'll reply ${wait}.`
    : `Thanks for asking! I want to give you an accurate price, so I've asked a team member to confirm it. They'll reply ${wait}.`;
  p.action = 'escalated_price'; p.escalate = true; p.reason = reason;
  p.alert_text = `Price needed (${reason}) for "${ctx.service_key}". Customer ${ctx.phone} asked: ${ctx.text}`;
} else {
  const type = String(get('price_type') ?? '').trim().toLowerCase();
  const display = `${type === 'from' ? 'from ' : ''}₦${price.toLocaleString('en-US')}${type === 'per_tooth' ? ' per tooth' : ''}`;
  let r = `Thanks${who}! ${get('service_name') || ctx.service_key} is ${display}.`;
  if (String(get('requires_consultation') ?? '').trim().toLowerCase() === 'yes') r += ' The final cost is confirmed at your consultation.';
  p.reply_text = `${r} Would you like to book a visit?`;
  p.action = 'price_sent';
}
return [{ json: p }];

// INPUT: the FAQ row found by "Lookup FAQ" (an empty item when nothing matched)
const ctx = $('Validate AI JSON').first().json;
const row = $input.first()?.json ?? {};
const cfg = ctx.config || {};
const wait = cfg.human_response_time || 'shortly';
const get = k => row[k] ?? row[`${k} (auto)`];

const p = { phone: ctx.phone, message_id: ctx.message_id, intent: ctx.intent, question: ctx.text,
  service_key: '', reply_text: '', action: '', result: 'ok', error: '',
  escalate: false, reason: '', alert_text: '', has_lead: false, lead: null };

const answer = String(get('approved_answer') ?? '').trim();
const active = String(get('status') ?? '').trim().toLowerCase() === 'active';
const found = !!get('faq_key') && active && answer !== '';
const yes = v => ['yes', 'true', 'y', '1'].includes(String(v ?? '').trim().toLowerCase());

// Safety net: an emergency is never left unanswered, even if the sheet row is missing or inactive
const EMERGENCY_FALLBACK = "I'm sorry you're in pain. A team member will contact you shortly. If you have swelling that affects your breathing or swallowing, or bleeding that won't stop, please go to your nearest hospital emergency department right away.";

if (found) {
  p.reply_text = answer;                                  // sent word for word
  p.action = 'faq_answered';
  if (yes(get('human_followup'))) {
    p.escalate = true; p.reason = 'faq_followup:' + ctx.faq_key;
    p.alert_text = `${ctx.faq_key === 'emergency' ? 'URGENT: ' : ''}Follow-up needed (${ctx.faq_key}). Customer ${ctx.phone} asked: ${ctx.text}`;
  }
} else if (ctx.faq_key === 'emergency') {
  p.reply_text = EMERGENCY_FALLBACK;
  p.action = 'faq_emergency_fallback'; p.escalate = true; p.reason = 'emergency_faq_missing';
  p.alert_text = `URGENT: emergency message, FAQ row missing. Customer ${ctx.phone} wrote: ${ctx.text}`;
} else {
  p.reply_text = `Thanks for your message! A team member will reply ${wait}.`;
  p.action = 'escalated_faq_missing'; p.escalate = true; p.reason = 'faq_not_found';
  p.alert_text = `No approved FAQ for "${ctx.faq_key}". Customer ${ctx.phone} asked: ${ctx.text}`;
}
return [{ json: p }];

// INPUT: the customer's existing row from "Lookup Lead" (an empty item for a new customer)
const ctx = $('Validate AI JSON').first().json;
const old = $input.first()?.json ?? {};
const cfg = ctx.config || {};
const clean = v => (v === null || v === undefined || String(v).trim() === '' || String(v).trim() === 'unknown') ? '' : String(v).trim();
const hhmm = v => {                                       // "09:00" stays "09:00"; Google's 0.375 becomes "09:00"
  if (typeof v === 'number') { const m = Math.round(v * 1440); return String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0'); }
  return String(v ?? '').trim();
};

// Only a name the customer actually typed counts. The WhatsApp profile name is just a fallback for greetings.
const lead = {
  phone: ctx.phone,
  name: clean(ctx.stated_name) || clean(old.name),
  service: clean(ctx.service_key) || clean(old.service),
  budget: clean(ctx.budget) || clean(old.budget),
  timeline: clean(ctx.timeline) || clean(old.timeline),
  last_message: ctx.text,
  updated_at: new Date().toISOString()
};

const TIMELINE = /\b(asap|today|tonight|tomorrow|soon|urgent|now|this (week|month)|next (week|month)|weeks?|days?)\b/i;
let score = 0;
if (lead.service) score += 30;
if (lead.budget) score += 20;
if (TIMELINE.test(lead.timeline)) score += 30;
if (lead.name) score += 20;
lead.score = score;
lead.status = score >= 70 ? 'hot' : score >= 40 ? 'warm' : 'cold';

const days = String(cfg.open_days || '').replace(/,/g, ', ');
const hours = days ? `${days}, ${hhmm(cfg.open_time)} to ${hhmm(cfg.close_time)}` : 'Monday to Saturday';
let reply;
if (!lead.service) reply = 'Thanks for reaching out to BrightSmile! Which service are you interested in? (for example cleaning, whitening, braces)';
else if (!lead.timeline) reply = `Great${lead.name ? ', ' + lead.name : ''}! When would you like to come in?`;
else if (!lead.name) reply = 'Lovely. May I have your name, please?';
else reply = `Thanks ${lead.name}! Would you like me to book a time? Tell me a day and time (${hours}).`;

const wasHot = clean(old.status).toLowerCase() === 'hot';   // alert once, not on every message
return [{ json: {
  phone: ctx.phone, message_id: ctx.message_id, intent: ctx.intent, question: ctx.text,
  service_key: lead.service, reply_text: reply, action: 'lead_updated', result: 'ok', error: '',
  escalate: false, reason: '',
  alert_text: (lead.status === 'hot' && !wasHot)
    ? `HOT LEAD (${score}): ${lead.name || 'name unknown'}, ${ctx.phone}, wants ${lead.service}, timeline: ${lead.timeline}` : '',
  has_lead: true, lead
}}];

const ctx = $('Validate AI JSON').first().json;
const cfg = ctx.config || {};
const row = $input.first()?.json ?? {};               // Pricing row from "Lookup Duration" (empty if the service is unknown)
const hhmm = v => {
  if (typeof v === 'number') { const m = Math.round(v * 1440); return String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0'); }
  return String(v ?? '').trim();
};
const openT = hhmm(cfg.open_time), closeT = hhmm(cfg.close_time);
const mins = Number(row.duration_mins) || 30;
const title = row.service_name || 'Consultation';
const hours = `${String(cfg.open_days).replace(/,/g, ', ')}, ${openT} to ${closeT}`;

const base = { phone: ctx.phone, message_id: ctx.message_id, intent: ctx.intent, question: ctx.text,
  service_key: ctx.service_key || '', escalate: false, reason: '', alert_text: '',
  has_lead: false, lead: null, error: '', result: 'ok' };
const bad = (msg, action) => [{ json: { ...base, valid: false, action, reply_text: msg } }];

if (!ctx.preferred_datetime) return bad(`Which day and time would you like? We're open ${hours}.`, 'ask_datetime');
const start = new Date(ctx.preferred_datetime);
if (isNaN(start)) return bad(`Sorry, I couldn't read that time. Please tell me a day and time, for example "Friday 2pm". We're open ${hours}.`, 'ask_datetime');

const end = new Date(start.getTime() + mins * 60000);
const L = new Date(start.getTime() + 3600000);   // Lagos local time (UTC+1, no daylight saving)
const E = new Date(end.getTime() + 3600000);
const day = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][L.getUTCDay()];
const toMin = t => { const [h, m] = String(t).split(':').map(Number); return h * 60 + m; };
const startMin = L.getUTCHours() * 60 + L.getUTCMinutes();
const endMin = E.getUTCHours() * 60 + E.getUTCMinutes();
const openDays = String(cfg.open_days).split(',').map(s => s.trim());
const notice = Number(cfg.min_notice_hours || 4) * 3600000;

if (start.getTime() < Date.now() + notice)
  return bad(`We need at least ${cfg.min_notice_hours || 4} hours' notice. Please pick a later time. We're open ${hours}.`, 'ask_datetime');
if (!openDays.includes(day) || startMin < toMin(openT) || endMin > toMin(closeT) || endMin <= startMin)
  return bad(`That time is outside our opening hours. We're open ${hours}. What other time suits you?`, 'ask_datetime');

return [{ json: { ...base, valid: true, start: start.toISOString(), end: end.toISOString(), title, mins,
  name: ctx.stated_name || ctx.profile_name || ctx.name } }];

const b = $('Booking Check').first().json;
if (!$json.id) {   // no event ID means NOT booked
  return [{ json: { ...b, escalate: true, reason: 'calendar_no_event_id', action: 'booking_failed', result: 'failed',
    error: 'Calendar returned no event id',
    reply_text: "I couldn't confirm that booking just now, so nothing is booked yet. A team member will confirm your slot shortly.",
    alert_text: `Booking needs manual confirmation: ${b.phone}, ${b.title}, ${b.start}` } }];
}
const when = new Date(b.start).toLocaleString('en-GB', { timeZone: 'Africa/Lagos', weekday: 'long',
  day: 'numeric', month: 'long', hour: 'numeric', minute: '2-digit', hour12: true });
const addr = $('Validate AI JSON').first().json.config.address;
return [{ json: { ...b, action: 'booking_created',
  reply_text: `You're booked for ${b.title} on ${when}. We're at ${addr}. Message us here if you need to change it.` } }];

const b = $('Booking Check').first().json;
return [{ json: { ...b, escalate: true, reason: 'calendar_failed', action: 'booking_failed', result: 'failed',
  error: String($json.error?.message ?? $json.error ?? 'calendar error'),
  reply_text: "I couldn't check the calendar just now, so I haven't booked anything. A team member will confirm your slot shortly.",
  alert_text: `Calendar failed while booking for ${b.phone} (${b.title}, ${b.start}). Please confirm manually.` } }];

const ctx = $input.first().json;
const cfg = ctx.config || {};
const wait = cfg.human_response_time || 'shortly';
const nm = ctx.profile_name && ctx.profile_name !== 'there' ? ' ' + ctx.profile_name : '';
const GREETING = /^\s*(hi+|hello+|hey+|hiya|good\s*(morning|afternoon|evening|day)|morning|afternoon|evening|how far)[\s!.,?]*$/i;
const soft = ['other_intent', 'low_confidence', 'invalid_json', 'invalid_json_shape', 'bad_faq_key'];

const base = { phone: ctx.phone, message_id: ctx.message_id, intent: ctx.intent || 'unclear', question: ctx.text,
  service_key: ctx.service_key || '', has_lead: false, lead: null };

// A plain greeting should not page a human
if (GREETING.test(ctx.text || '') && (!ctx.reason || soft.includes(ctx.reason))) {
  return [{ json: { ...base, intent: 'greeting',
    reply_text: `Hello${nm}! Welcome to ${cfg.business_name || 'BrightSmile'}. I can help with prices, opening hours and bookings. What would you like to know?`,
    action: 'greeting', result: 'ok', error: '', escalate: false, reason: '', alert_text: '' } }];
}

return [{ json: { ...base,
  reply_text: `Thanks for your message! A team member will reply ${wait}.`,
  action: 'escalated', result: 'ok',
  error: ['invalid_json', 'invalid_json_shape'].includes(ctx.reason) ? 'AI returned invalid JSON' : '',
  escalate: true, reason: ctx.reason || 'other_intent',
  alert_text: `Needs a human (${ctx.reason || 'other'}): ${ctx.phone} wrote: ${ctx.text}` } }];

const base = $('Merge Config').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.phone);   // an empty item means "no history yet"

const WINDOW_MINUTES = 120;   // forget anything older than this
const MAX_TURNS = 10;         // keep at most this many exchanges

const toTime = v => {
  if (v === undefined || v === null || String(v).trim() === '') return NaN;
  const s = String(v).trim();
  if (/^\d{5}(\.\d+)?$/.test(s)) return Math.round((Number(s) - 25569) * 86400000);   // Google serial date
  return Date.parse(s);
};
const clip = s => (s.length > 300 ? s.slice(0, 300) + '…' : s);

const cutoff = Date.now() - WINDOW_MINUTES * 60000;
const turns = rows
  .map(r => ({ t: toTime(r.time), user: String(r.customer_text ?? '').trim(), bot: String(r.bot_reply ?? '').trim() }))
  .filter(x => Number.isFinite(x.t) && x.t >= cutoff && (x.user || x.bot))
  .sort((a, b) => a.t - b.t)
  .slice(-MAX_TURNS);

const history = turns.map(x => `Customer: ${clip(x.user)}\nAssistant: ${clip(x.bot)}`).join('\n');
return [{ json: { ...base, history: history || '(no earlier messages)' } }];
